      .randomize-btn {
        position: absolute;
        top: 50%;
        right: 0;
        transform: translateY(-50%);
        cursor: pointer;
        color: var(--text-secondary-color);
        transition: all 0.2s ease-in-out;
      }
      .randomize-btn:hover {
